<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Clerk'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$candidateId=filter_var($_POST['candidate_id']??null,FILTER_VALIDATE_INT);$subjectIds=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['subject_ids']??[])),fn($id)=>$id>0)));$repeatData=is_array($_POST['repeat']??null)?$_POST['repeat']:[];if(!$candidateId||!$subjectIds){$_SESSION['error']='Select at least one subject for this candidate.';header('Location: ../?page=exams&candidate='.(int)$candidateId);exit;}
$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT ec.id,ec.status,es.id AS session_id,es.level,es.exam_year,es.status AS session_status,es.opens_on,es.entry_deadline FROM exam_candidates ec JOIN exam_sessions es ON es.id=ec.session_id WHERE ec.id=:id FOR UPDATE');$q->execute(['id'=>$candidateId]);$candidate=$q->fetch();$today=date('Y-m-d');if(!$candidate||$candidate['status']!=='Draft'||$candidate['session_status']!=='Open'||$today<$candidate['opens_on']||$today>$candidate['entry_deadline'])throw new DomainException('Only draft candidates in an open entry window can change subjects.');if($candidate['level']==='O-Level'&&count($subjectIds)>9)throw new DomainException('ZIMSEC O-Level entries cannot exceed nine subjects.');$in=implode(',',array_fill(0,count($subjectIds),'?'));$q=$pdo->prepare("SELECT ess.subject_id,ess.option_group FROM exam_session_subjects ess JOIN subjects s ON s.id=ess.subject_id AND s.active=1 WHERE ess.session_id=? AND ess.subject_id IN ($in)");$q->execute(array_merge([(int)$candidate['session_id']],$subjectIds));$offerRows=$q->fetchAll();if(count($offerRows)!==count($subjectIds))throw new DomainException('Choose only subjects offered for this examination session.');$groups=[];$groupById=[];foreach($offerRows as $r){$groupById[(int)$r['subject_id']]=$r['option_group'];if($r['option_group']){$key=strtoupper(trim($r['option_group']));if(isset($groups[$key]))throw new DomainException('Only one subject can be selected from option group '.$r['option_group'].'.');$groups[$key]=true;}}
$clean=[];foreach($subjectIds as $sid){$r=is_array($repeatData[$sid]??null)?$repeatData[$sid]:[];$isRepeat=isset($r['is_repeat'])&&$r['is_repeat']==='1';$year=filter_var($r['previous_year']??null,FILTER_VALIDATE_INT);$centre=strtoupper(trim((string)($r['previous_centre_number']??'')));$number=trim((string)($r['previous_candidate_number']??''));if($isRepeat&&(!$year||$year<1990||$year>=(int)$candidate['exam_year']||$centre===''||strlen($centre)>30||$number===''||strlen($number)>24))throw new DomainException('For each repeat subject, provide its previous exam year, centre number and candidate number.');$clean[]=['id'=>$sid,'repeat'=>$isRepeat,'year'=>$isRepeat?$year:null,'centre'=>$isRepeat?$centre:null,'number'=>$isRepeat?$number:null];}
$q=$pdo->prepare('DELETE FROM exam_candidate_subjects WHERE candidate_id=:id');$q->execute(['id'=>$candidateId]);$q=$pdo->prepare('INSERT INTO exam_candidate_subjects(candidate_id,subject_id,is_repeat,previous_year,previous_centre_number,previous_candidate_number) VALUES(:candidate,:subject,:repeat,:year,:centre,:number)');foreach($clean as $r)$q->execute(['candidate'=>$candidateId,'subject'=>$r['id'],'repeat'=>$r['repeat']?1:0,'year'=>$r['year'],'centre'=>$r['centre'],'number'=>$r['number']]);audit_log('exams.subjects_saved','exam_candidates',$candidateId,['subject_count'=>count($clean),'repeat_subjects'=>count(array_filter($clean,fn($r)=>$r['repeat']))]);$pdo->commit();$_SESSION['notice']='Candidate subject entries saved as a draft.';}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Exam subjects save failed: '.$e->getMessage());$_SESSION['error']='Could not save the candidate subject entries.';}header('Location: ../?page=exams&session='.(int)($candidate['session_id']??0).'&candidate='.(int)$candidateId);exit;
